{
    let message = String::from("hello, Rust");
    println!("{message}");
} // message goes out of scope and is dropped

let original = String::from("a small idea");
let next = original;

println!("{next}"); // valid
// println!("{original}"); // the value has moved

let title = String::from("The shape of an idea");
let first_reader = &title;
let second_reader = &title;

println!("{first_reader} · {second_reader}");

let mut idea = String::from("ownership");
let editor = &mut idea;
editor.push_str(" makes responsibility visible");

println!("{editor}");
